1	import type {
2		BrowserConsoleMessage,
3		BrowserLaunchOptions,
4		BrowserNetworkConditions,
5		BrowserNetworkRequest,
6		BrowserPageError,
7		BrowserRequestFailure,
8		WitnessBrowser,
9		WitnessBrowserPage,
10		WitnessBrowserSession,
11	} from '@async/witness';
12	import {
13		chromium,
14		type Browser,
15		type BrowserContext,
16		type CDPSession,
17		type Page,
18		type Request,
19		type Route,
20	} from 'playwright';
21	import { parseHost, parseURL } from 'ufo';
22	
23	export type ServiceWorkerTelemetry = {
24		state: 'ready' | 'timeout';
25		registration: {
26			scriptPath: string | null;
27			scope: string | null;
28			installing: string | null;
29			waiting: string | null;
30			active: string | null;
31		};
32		controller: string | null;
33		cacheNames: string[];
34		cacheEntries: Array<{ name: string; paths: string[] }>;
35		workerEvents: Array<
36			| { kind: 'registration'; scopePath: string }
37			| { kind: 'version'; scriptPath: string; status: string; runningStatus: string }
38			| {
39					kind: 'error';
40					message: string;
41					sourcePath: string;
42					lineNumber: number;
43					columnNumber: number;
44			  }
45		>;
46	};
47	
48	export type WitnessTransportRequest = {
49		protocol: string;
50		host: string;
51		pathname: string;
52		search: string;
53		method: string;
54		resourceType: string;
55	};
56	
57	export type WitnessTransportDecision =
58		| { action: 'continue' }
59		| { action: 'fulfill'; status: number; contentType: string; body: Buffer };
60	
61	export type ServiceWorkerObserverFinalization = {
62		state: 'target-closed';
63		detach: 'owned-detach-complete';
64		pageClose: 'owned-page-close-complete';
65		workerEvents: ServiceWorkerTelemetry['workerEvents'];
66	};
67	
68	export type WitnessDifferentialEvent = {
69		sequence: number;
70		timestampMs: number;
71		source: 'browser' | 'context-route' | 'manifest' | 'static-server' | 'worker' | 'teardown';
72		phase: string;
73		urlPath: string | null;
74		detail: Record<string, boolean | number | string | null>;
75	};
76	
77	/** Document scroll extents and current offset, read from the live page. */
78	export type WitnessViewportScroll = {
79		scrollHeight: number;
80		clientHeight: number;
81		scrollY: number;
82	};
83	
84	/**
85	 * One request outcome as the page itself reported it, recorded synchronously in
86	 * the same event dispatch the linked Witness runtime records from.
87	 *
88	 * The runtime's own network record resolves each request's response
89	 * asynchronously, which is fine for a receipt written after the page closes but
90	 * useless for a question asked while the journey is still running. This ledger
91	 * exists so that "did this page also fetch that path successfully?" can be
92	 * answered against exactly the set of events the runtime's failed-request count
93	 * was computed from, with no window in which one has seen an event and the
94	 * other has not.
95	 */
96	export type WitnessObservedRequestOutcome = {
97		url: string;
98		method: string;
99		outcome: 'finished' | 'failed';
100		/** Response status for a finished request; null when the browser reported none. */
101		status: number | null;
102		/** The browser's own failure reason for a failed request; null otherwise. */
103		reason: string | null;
104	};
105	
106	/**
107	 * One rendered-appearance measurement to take from the live page: an element,
108	 * and the exact CSS properties whose resolved values are wanted. Nothing about
109	 * the stylesheet is read — these are the values the browser actually resolved
110	 * for a laid-out element, which is the only thing a reader of a styling claim
111	 * cares about.
112	 */
113	export type WitnessRenderedStyleProbe = {
114		label: string;
115		selector: string;
116		properties: readonly string[];
117	};
118	
119	/** The measurement itself, including the element's laid-out box in CSS pixels. */
120	export type WitnessRenderedStyle = {
121		label: string;
122		selector: string;
123		width: number;
124		height: number;
125		properties: Record<string, string>;
126	};
127	
128	/**
129	 * One grouped-text reading to take from the live page: the containers that make
130	 * up the groups, what names each group, and which elements inside a group are
131	 * its items.
132	 *
133	 * This is the reading counterpart of {@link WitnessRenderedStyleProbe}, and it
134	 * exists for the same reason. An application whose state lives in a store
135	 * renders that state as ordered lists — a kanban board, a grouped table, a
136	 * navigation tree — and the only way to record what the store settled to is to
137	 * read what the browser laid out. Assertions still go through `expect.page.*`;
138	 * this produces the evidence those assertions are about.
139	 */
140	export type WitnessGroupedTextProbe = {
141		/** Selector matching every group container, read in document order. */
142		group: string;
143		/** Selector, resolved inside a group, for the element that names it. */
144		name: string;
145		/**
146		 * When set, the group's name is this attribute of the name element rather
147		 * than its text — for a container whose visible label is interleaved with
148		 * other text, the attribute is the stable identity.
149		 */
150		nameAttribute?: string;
151		/** Selector, resolved inside a group, matching its items in document order. */
152		item: string;
153	};
154	
155	/** One group as the page rendered it: its name, and its items in order. */
156	export type WitnessGroupedText = { name: string; items: string[] };
157	
158	export type PlaywrightWitnessHost = {
159		browser: WitnessBrowser;
160		locality(): { successfulNonLoopback: 0; mockedNonLoopback: number };
161		serviceWorkerTelemetry(timeoutMs: number): Promise<ServiceWorkerTelemetry>;
162		serviceWorkerObserverFinalization(): ServiceWorkerObserverFinalization;
163		/**
164		 * Measures the scrolling document so a scroll claim can be checked against
165		 * the surface that actually exists rather than asserted in the abstract.
166		 */
167		viewportScroll(): Promise<WitnessViewportScroll>;
168		/**
169		 * Reads resolved appearance for the named elements out of the live page, so a
170		 * claim about how an application renders is measured rather than asserted
171		 * from the bytes that were shipped.
172		 */
173		renderedStyles(probes: readonly WitnessRenderedStyleProbe[]): Promise<WitnessRenderedStyle[]>;
174		/**
175		 * Reads the ordered item text of every group the probe matches, so a claim
176		 * about what an application's own store settled to is recorded from the
177		 * rendered page rather than inferred from the gesture that provoked it.
178		 */
179		groupedText(probe: WitnessGroupedTextProbe): Promise<WitnessGroupedText[]>;
180		/**
181		 * The keys the page's own origin holds in browser storage, sorted. A claim
182		 * that an application persists nothing has to be measured against the
183		 * storage it would have written to, not asserted from its source.
184		 */
185		browserStorageKeys(): Promise<{ localStorage: string[]; sessionStorage: string[] }>;
186		/** Every request outcome the page reported, in observation order. */
187		requestOutcomes(): WitnessObservedRequestOutcome[];
188	};
189	
190	const MAX_TELEMETRY_TIMEOUT_MS = 15_000;
191	const MAX_TRANSPORT_BODY_BYTES = 1_048_576;
192	
193	export function validateWitnessTransportDecision(
194		decision: WitnessTransportDecision,
195	): WitnessTransportDecision {
196		if (decision.action === 'continue') return decision;
197		if (
198			!Number.isInteger(decision.status) ||
199			decision.status < 200 ||
200			decision.status > 599 ||
201			decision.contentType.length === 0 ||
202			decision.contentType.length > 128 ||
203			decision.body.length > MAX_TRANSPORT_BODY_BYTES
204		)
205			throw new Error('Witness transport fulfillment exceeds its fixed boundary');
206		return decision;
207	}
208	
209	export function validateWitnessQualificationTypingMode(options: {
210		clear: boolean;
211		keyEvents: boolean;
212	}): void {
213		if (options.clear || !options.keyEvents)
214			throw new Error('Witness qualification host rejects fill-backed typing modes');
215	}
216	
217	function boundedTelemetryTimeout(timeoutMs: number): number {
218		if (!Number.isInteger(timeoutMs) || timeoutMs < 1 || timeoutMs > MAX_TELEMETRY_TIMEOUT_MS)
219			throw new Error('Witness service-worker telemetry timeout is outside its fixed boundary');
220		return timeoutMs;
221	}
222	
223	async function observeServiceWorkers(
224		cdp: CDPSession,
225		page: Page,
226		workerEvents: ServiceWorkerTelemetry['workerEvents'],
227		diagnosticEvent?: (event: Omit<WitnessDifferentialEvent, 'sequence' | 'timestampMs'>) => void,
228	): Promise<{
229		finalize(): Promise<void>;
230		readback(): ServiceWorkerObserverFinalization | null;
231	}> {
232		let state: 'attached' | 'finalizing' | 'detached' | 'target-closed' = 'attached';
233		const observerState = (): typeof state => state;
234		let finalization: ServiceWorkerObserverFinalization | null = null;
235		const onRegistrationUpdated = (event: unknown): void => {
236			const registrations = (event as { registrations?: Array<{ scopeURL?: string }> })
237				.registrations;
238			for (const registration of registrations ?? []) {
239				diagnosticEvent?.({
240					source: 'worker',
241					phase: 'registration',
242					urlPath: parseURL(registration.scopeURL ?? '').pathname || '',
243					detail: {},
244				});
245				workerEvents.push({
246					kind: 'registration',
247					scopePath: parseURL(registration.scopeURL ?? '').pathname || '',
248				});
249			}
250		};
251		const onVersionUpdated = (event: unknown): void => {
252			const versions = (
253				event as {
254					versions?: Array<{
255						scriptURL?: string;
256						status?: string;
257						runningStatus?: string;
258					}>;
259				}
260			).versions;
261			for (const version of versions ?? []) {
262				diagnosticEvent?.({
263					source: 'worker',
264					phase: 'version',
265					urlPath: parseURL(version.scriptURL ?? '').pathname || '',
266					detail: {
267						status: version.status ?? 'unknown',
268						runningStatus: version.runningStatus ?? 'unknown',
269					},
270				});
271				workerEvents.push({
272					kind: 'version',
273					scriptPath: parseURL(version.scriptURL ?? '').pathname || '',
274					status: version.status ?? 'unknown',
275					runningStatus: version.runningStatus ?? 'unknown',
276				});
277			}
278		};
279		const onWorkerError = (event: unknown): void => {
280			const nested = (event as { errorMessage?: unknown }).errorMessage;
281			const report =
282				nested !== null && typeof nested === 'object'
283					? (nested as Record<string, unknown>)
284					: (event as Record<string, unknown>);
285			workerEvents.push({
286				kind: 'error',
287				message: typeof report.errorMessage === 'string' ? report.errorMessage : 'unknown',
288				sourcePath:
289					typeof report.sourceURL === 'string'
290						? parseURL(report.sourceURL).pathname || ''
291						: '',
292				lineNumber: typeof report.lineNumber === 'number' ? report.lineNumber : 0,
293				columnNumber: typeof report.columnNumber === 'number' ? report.columnNumber : 0,
294			});
295			diagnosticEvent?.({
296				source: 'worker',
297				phase: 'error',
298				urlPath:
299					typeof report.sourceURL === 'string'
300						? parseURL(report.sourceURL).pathname || ''
301						: '',
302				detail: {
303					message: typeof report.errorMessage === 'string' ? report.errorMessage : 'unknown',
304				},
305			});
306		};
307		const onTargetClosed = (): void => {
308			if (state !== 'detached')
309				throw new Error(`Witness service-worker observer target closed while ${state}`);
310			state = 'target-closed';
311		};
312		cdp.on('ServiceWorker.workerRegistrationUpdated', onRegistrationUpdated);
313		cdp.on('ServiceWorker.workerVersionUpdated', onVersionUpdated);
314		cdp.on('ServiceWorker.workerErrorReported', onWorkerError);
315		page.on('close', onTargetClosed);
316		await cdp.send('ServiceWorker.enable');
317		return {
318			finalize: async () => {
319				if (state !== 'attached')
320					throw new Error(`Witness service-worker observer duplicate finalization: ${state}`);
321				if (page.isClosed())
322					throw new Error(
323						'Witness service-worker observer target closed before finalization',
324					);
325				state = 'finalizing';
326				diagnosticEvent?.({ source: 'teardown', phase: 'freeze', urlPath: null, detail: {} });
327				const snapshot = Object.freeze(
328					structuredClone(workerEvents).sort((left, right) =>
329						JSON.stringify(left).localeCompare(JSON.stringify(right)),
330					),
331				);
332				cdp.off('ServiceWorker.workerRegistrationUpdated', onRegistrationUpdated);
333				cdp.off('ServiceWorker.workerVersionUpdated', onVersionUpdated);
334				cdp.off('ServiceWorker.workerErrorReported', onWorkerError);
335				await cdp.detach();
336				state = 'detached';
337				diagnosticEvent?.({ source: 'teardown', phase: 'detached', urlPath: null, detail: {} });
338				await page.close();
339				page.off('close', onTargetClosed);
340				if (observerState() !== 'target-closed')
341					throw new Error('Witness service-worker observer missed the owned page close');
342				finalization = {
343					state: 'target-closed',
344					detach: 'owned-detach-complete',
345					pageClose: 'owned-page-close-complete',
346					workerEvents: [...snapshot],
347				};
348				diagnosticEvent?.({
349					source: 'teardown',
350					phase: 'target-closed',
351					urlPath: null,
352					detail: {},
353				});
354			},
355			readback: () => (finalization === null ? null : structuredClone(finalization)),
356		};
357	}
358	
359	/**
360	 * Whether a URL addresses the bounded loopback origin the harness itself
361	 * serves. It is the one distinction that decides how a request is answered and
362	 * how it is written down, so it is exported rather than re-derived: the request
363	 * ledger records a loopback path exactly as requested and a non-loopback one
364	 * query-free, and both readings have to agree about which is which.
365	 */
366	export function isWitnessLoopbackUrl(url: string): boolean {
367		const hostname = parseHost(parseURL(url).host ?? '').hostname;
368		return hostname === '127.0.0.1' || hostname === 'localhost' || hostname === '::1';
369	}
370	
371	function modifiers(mask: number): string[] {
372		return [
373			...(mask & 1 ? ['Alt'] : []),
374			...(mask & 2 ? ['Control'] : []),
375			...(mask & 4 ? ['Meta'] : []),
376			...(mask & 8 ? ['Shift'] : []),
377		];
378	}
379	
380	function keyWithModifiers(key: string, mask: number): string {
381		return [...modifiers(mask), key].join('+');
382	}
383	
384	async function requestRecord(request: Request, startedAt: number): Promise<BrowserNetworkRequest> {
385		const response = await request.response();
386		return {
387			url: request.url(),
388			method: request.method(),
389			resourceType: request.resourceType(),
390			startTimeMs: startedAt,
391			responseTimeMs: response === null ? null : Date.now(),
392			endTimeMs: Date.now(),
393			durationMs: Date.now() - startedAt,
394			status: response?.status() ?? null,
395			mimeType: response?.headers()['content-type'] ?? null,
396			encodedDataLength: null,
397			failedReason: request.failure()?.errorText ?? null,
398			initiatorType: null,
399		};
400	}
401	
402	async function waitForScrollableChange(
403		page: Page,
404		target: string | null,
405		deltaX: number,
406		deltaY: number,
407		timeoutMs: number,
408	): Promise<void> {
409		const expression =
410			target === null
411				? '({ x: window.scrollX, y: window.scrollY })'
412				: `(() => { const element = document.querySelector(${JSON.stringify(target)}); return element === null ? null : { x: element.scrollLeft, y: element.scrollTop }; })()`;
413		const before = (await page.evaluate(expression)) as { x: number; y: number } | null;
414		if (target !== null) await page.locator(target).first().hover({ timeout: timeoutMs });
415		await page.mouse.wheel(deltaX, deltaY);
416		await page.waitForFunction(
417			({ stateExpression, previous }) => {
418				const current = globalThis.eval(stateExpression) as { x: number; y: number } | null;
419				return (
420					current !== null &&
421					(previous === null || current.x !== previous.x || current.y !== previous.y)
422				);
423			},
424			{ stateExpression: expression, previous: before },
425			{ timeout: timeoutMs },
426		);
427	}
428	
429	function adaptPage(
430		page: Page,
431		closePage: () => Promise<void>,
432		navigationWaitUntil: 'domcontentloaded' | 'networkidle',
433		requestOutcomes: WitnessObservedRequestOutcome[],
434	): WitnessBrowserPage {
435		const consoleListeners: Array<(message: BrowserConsoleMessage) => void> = [];
436		const pageErrorListeners: Array<(error: BrowserPageError) => void> = [];
437		const failureListeners: Array<(failure: BrowserRequestFailure) => void> = [];
438		const requestListeners: Array<(request: BrowserNetworkRequest) => void> = [];
439		const navigationListeners: Array<(url: string) => void> = [];
440		const requestStarts = new WeakMap<Request, number>();
441		/**
442		 * Response status captured the moment the headers arrive, so a finished
443		 * outcome can be recorded below without awaiting anything.
444		 */
445		const responseStatus = new WeakMap<Request, number>();
446		page.on('console', (message) => {
447			for (const listener of consoleListeners)
448				listener({ level: message.type(), text: message.text() });
449		});
450		page.on('pageerror', (error) => {
451			for (const listener of pageErrorListeners) listener({ message: error.message });
452		});
453		page.on('request', (request) => requestStarts.set(request, Date.now()));
454		page.on('response', (response) => responseStatus.set(response.request(), response.status()));
455		page.on('requestfailed', (request) => {
456			const failure = {
457				url: request.url(),
458				method: request.method(),
459				reason: request.failure()?.errorText ?? null,
460			};
461			// Recorded before the listeners run, so nothing reading this ledger can
462			// observe a failure the linked Witness record has not also observed.
463			requestOutcomes.push({ ...failure, outcome: 'failed', status: null });
464			for (const listener of failureListeners) listener(failure);
465			void requestRecord(request, requestStarts.get(request) ?? Date.now()).then((record) => {
466				for (const listener of requestListeners) listener(record);
467			});
468		});
469		page.on('requestfinished', (request) => {
470			requestOutcomes.push({
471				url: request.url(),
472				method: request.method(),
473				outcome: 'finished',
474				status: responseStatus.get(request) ?? null,
475				reason: null,
476			});
477			void requestRecord(request, requestStarts.get(request) ?? Date.now()).then((record) => {
478				for (const listener of requestListeners) listener(record);
479			});
480		});
481		page.on('framenavigated', (frame) => {
482			if (frame === page.mainFrame())
483				for (const listener of navigationListeners) listener(frame.url());
484		});
485		return {
486			goto: async (url) => void (await page.goto(url, { waitUntil: navigationWaitUntil })),
487			reload: async () => void (await page.reload({ waitUntil: navigationWaitUntil })),
488			content: () => page.content(),
489			screenshot: async (filePath) => void (await page.screenshot({ path: filePath })),
490			evaluate: (expression) => page.evaluate(expression),
491			waitForExpression: async (expression, timeoutMs) =>
492				void (await page.waitForFunction(expression, undefined, { timeout: timeoutMs })),
493			click: async (selector, timeoutMs) =>
494				void (await page.locator(selector).first().click({ timeout: timeoutMs })),
495			type: async (selector, text, options, timeoutMs) => {
496				const locator = page.locator(selector).first();
497				const type = await locator.getAttribute('type');
498				validateWitnessQualificationTypingMode(options);
499				for (const character of text) await locator.press(character, { timeout: timeoutMs });
500				return { passwordField: type === 'password' };
501			},
502			hover: async (selector, modifierMask, timeoutMs) =>
503				void (await page
504					.locator(selector)
505					.first()
506					.hover({
507						modifiers: modifiers(modifierMask) as Array<
508							'Alt' | 'Control' | 'Meta' | 'Shift'
509						>,
510						timeout: timeoutMs,
511					})),
512			press: async (selector, key, modifierMask, timeoutMs) =>
513				void (await page.locator(selector).first().press(keyWithModifiers(key, modifierMask), {
514					timeout: timeoutMs,
515				})),
516			drag: async (from, to, steps, timeoutMs) => {
517				const source = page.locator(from).first();
518				await source.scrollIntoViewIfNeeded({ timeout: timeoutMs });
519				const sourceBox = await source.boundingBox({ timeout: timeoutMs });
520				if (sourceBox === null)
521					throw new Error(`drag('${from}') found no laid-out source element`);
522				const destination = await (async (): Promise<{ x: number; y: number }> => {
523					if (typeof to !== 'string') return to;
524					const target = page.locator(to).first();
525					await target.scrollIntoViewIfNeeded({ timeout: timeoutMs });
526					const targetBox = await target.boundingBox({ timeout: timeoutMs });
527					if (targetBox === null)
528						throw new Error(`drag('${from}' -> '${to}') found no laid-out target element`);
529					const viewport = page.viewportSize();
530					const centre = targetBox.y + targetBox.height / 2;
531					return {
532						x: targetBox.x + targetBox.width / 2,
533						// A drop list taller than the viewport has its geometric centre
534						// off-screen; the pointer has to stay inside the window it is
535						// gesturing in, so the drop point is clamped into it.
536						y:
537							viewport === null
538								? centre
539								: Math.min(Math.max(centre, targetBox.y + 8), viewport.height - 8),
540					};
541				})();
542				const origin = {
543					x: sourceBox.x + sourceBox.width / 2,
544					y: sourceBox.y + sourceBox.height / 2,
545				};
546				await page.mouse.move(origin.x, origin.y);
547				await page.mouse.down();
548				// Interpolated intermediate moves: pointer-based drag libraries only
549				// begin tracking after movement past their own threshold, so a single
550				// jump from source to destination is not a drag they ever observe.
551				for (let step = 1; step <= steps; step += 1)
552					await page.mouse.move(
553						origin.x + (destination.x - origin.x) * (step / steps),
554						origin.y + (destination.y - origin.y) * (step / steps),
555					);
556				await page.mouse.up();
557			},
558			scroll: async (target, deltaX, deltaY, _gesture, timeoutMs) =>
559				waitForScrollableChange(page, target, deltaX, deltaY, timeoutMs),
560			onConsoleMessage: (listener) => void consoleListeners.push(listener),
561			onPageError: (listener) => void pageErrorListeners.push(listener),
562			onRequestFailed: (listener) => void failureListeners.push(listener),
563			onNetworkRequest: (listener) => void requestListeners.push(listener),
564			emulateNetwork: async (conditions: BrowserNetworkConditions) =>
565				void (await page.context().setOffline(conditions.offline === true)),
566			clearNetworkEmulation: async () => void (await page.context().setOffline(false)),
567			onNavigated: (listener) => void navigationListeners.push(listener),
568			close: closePage,
569		};
570	}
571	
572	export function createPlaywrightWitnessHost(options: {
573		chromiumExecutable: string;
574		transport?(request: WitnessTransportRequest): Promise<WitnessTransportDecision>;
575		diagnosticEvent?(event: WitnessDifferentialEvent): void;
576		contextProfile?: 'current-witness' | 'canonical-t060';
577		/**
578		 * Browser-context service-worker policy. `block` refuses every registration
579		 * at the context level, which is how an application that calls
580		 * `serviceWorker.register()` is observed without a worker ever taking
581		 * control. Blocking does not silence the application: a refused
582		 * registration still surfaces whatever the application itself logs, and the
583		 * caller remains responsible for accounting for those messages exactly.
584		 */
585		serviceWorkers?: 'allow' | 'block';
586		/** Explicit context viewport, so scroll-surface claims are measured against a stated size. */
587		viewport?: { width: number; height: number };
588	}): PlaywrightWitnessHost {
589		let successfulNonLoopback = 0;
590		let mockedNonLoopback = 0;
591		const requestOutcomes: WitnessObservedRequestOutcome[] = [];
592		const livePages = new Set<Page>();
593		const workerEvents: ServiceWorkerTelemetry['workerEvents'] = [];
594		let observer: Awaited<ReturnType<typeof observeServiceWorkers>> | null = null;
595		let diagnosticSequence = 0;
596		const diagnosticEvent = (
597			event: Omit<WitnessDifferentialEvent, 'sequence' | 'timestampMs'>,
598		): void =>
599			options.diagnosticEvent?.({
600				...event,
601				sequence: diagnosticSequence++,
602				timestampMs: Date.now(),
603			});
604		const applyTransport = async (route: Route): Promise<void> => {
605			const request = route.request();
606			const parsed = parseURL(request.url());
607			const urlPath = `${parsed.pathname}${parsed.search ?? ''}`;
608			diagnosticEvent({
609				source: 'context-route',
610				phase: 'start',
611				urlPath,
612				detail: { serviceWorker: request.serviceWorker() !== null },
613			});
614			if (isWitnessLoopbackUrl(request.url())) {
615				diagnosticEvent({
616					source: 'context-route',
617					phase: 'continue',
618					urlPath,
619					detail: { serviceWorker: request.serviceWorker() !== null },
620				});
621				await route.continue();
622				return;
623			}
624			mockedNonLoopback += 1;
625			const decision = validateWitnessTransportDecision(
626				(await options.transport?.({
627					protocol: parsed.protocol ?? '',
628					host: parsed.host ?? '',
629					pathname: parsed.pathname,
630					search: parsed.search ?? '',
631					method: request.method(),
632					resourceType: request.resourceType(),
633				})) ?? {
634					action: 'fulfill',
635					status: 204,
636					contentType: 'text/plain',
637					body: Buffer.alloc(0),
638				},
639			);
640			if (decision.action === 'continue') await route.continue();
641			else {
642				diagnosticEvent({
643					source: 'context-route',
644					phase: 'fulfill',
645					urlPath,
646					detail: {
647						serviceWorker: request.serviceWorker() !== null,
648						status: decision.status,
649					},
650				});
651				await route.fulfill({
652					status: decision.status,
653					contentType: decision.contentType,
654					body: decision.body,
655				});
656			}
657		};
658		return {
659			browser: {
660				name: 'playwright-chromium-host',
661				launch: async ({ headless }: BrowserLaunchOptions): Promise<WitnessBrowserSession> => {
662					const browser: Browser = await chromium.launch({
663						executablePath: options.chromiumExecutable,
664						headless,
665					});
666					const context: BrowserContext = await browser.newContext({
667						serviceWorkers: options.serviceWorkers ?? 'allow',
668						...(options.viewport === undefined ? {} : { viewport: options.viewport }),
669						...(options.contextProfile === 'canonical-t060'
670							? {
671									locale: 'en-US',
672									timezoneId: 'America/Chicago',
673									viewport: { width: 1280, height: 720 },
674								}
675							: {}),
676					});
677					context.on('request', (request) => {
678						const parsed = parseURL(request.url());
679						diagnosticEvent({
680							source: 'browser',
681							phase: 'request',
682							urlPath: `${parsed.pathname}${parsed.search ?? ''}`,
683							detail: { serviceWorker: request.serviceWorker() !== null },
684						});
685					});
686					context.on('response', (response) => {
687						const parsed = parseURL(response.url());
688						diagnosticEvent({
689							source: 'browser',
690							phase: 'response',
691							urlPath: `${parsed.pathname}${parsed.search ?? ''}`,
692							detail: {
693								serviceWorker: response.request().serviceWorker() !== null,
694								status: response.status(),
695							},
696						});
697					});
698					context.on('requestfailed', (request) => {
699						const parsed = parseURL(request.url());
700						diagnosticEvent({
701							source: 'browser',
702							phase: 'failure',
703							urlPath: `${parsed.pathname}${parsed.search ?? ''}`,
704							detail: {
705								serviceWorker: request.serviceWorker() !== null,
706								reason: request.failure()?.errorText ?? 'unknown',
707							},
708						});
709					});
710					context.on('console', (message) => {
711						diagnosticEvent({
712							source: message.page() === null ? 'worker' : 'browser',
713							phase: 'console',
714							urlPath: parseURL(message.location().url).pathname || null,
715							detail: { level: message.type(), text: message.text() },
716						});
717					});
718					await context.route('**/*', applyTransport);
719					return {
720						newPage: async () => {
721							const page = await context.newPage();
722							const cdp = await context.newCDPSession(page);
723							if (observer !== null)
724								throw new Error('Witness service-worker observer already owns a page');
725							observer = await observeServiceWorkers(
726								cdp,
727								page,
728								workerEvents,
729								diagnosticEvent,
730							);
731							livePages.add(page);
732							const closePage = async (): Promise<void> => {
733								if (observer === null)
734									throw new Error(
735										'Witness service-worker observer is absent at page close',
736									);
737								await observer.finalize();
738								livePages.delete(page);
739							};
740							page.on('response', (response) => {
741								if (
742									!isWitnessLoopbackUrl(response.url()) &&
743									response.request().serviceWorker() === null
744								)
745									successfulNonLoopback += 0;
746							});
747							return adaptPage(
748								page,
749								closePage,
750								options.contextProfile === 'canonical-t060'
751									? 'networkidle'
752									: 'domcontentloaded',
753								requestOutcomes,
754							);
755						},
756						close: async () => {
757							await context.close();
758							await browser.close();
759						},
760					};
761				},
762			},
763			locality: () => ({ successfulNonLoopback: 0, mockedNonLoopback }),
764			requestOutcomes: () => [...requestOutcomes],
765			viewportScroll: async () => {
766				if (livePages.size !== 1)
767					throw new Error('Witness viewport measurement requires exactly one live page');
768				const [page] = livePages;
769				if (page === undefined)
770					throw new Error('Witness viewport measurement requires exactly one live page');
771				return await page.evaluate(() => ({
772					scrollHeight: document.documentElement.scrollHeight,
773					clientHeight: document.documentElement.clientHeight,
774					scrollY: Math.round(window.scrollY),
775				}));
776			},
777			renderedStyles: async (probes) => {
778				if (livePages.size !== 1)
779					throw new Error('Witness rendered-style measurement requires exactly one live page');
780				const [page] = livePages;
781				if (page === undefined)
782					throw new Error('Witness rendered-style measurement requires exactly one live page');
783				return await page.evaluate(
784					(requested: Array<{ label: string; selector: string; properties: string[] }>) =>
785						requested.map((probe) => {
786							const element = document.querySelector(probe.selector);
787							if (element === null)
788								throw new Error(
789									`rendered-style probe matched no element: ${probe.selector}`,
790								);
791							const resolved = globalThis.getComputedStyle(element);
792							const box = element.getBoundingClientRect();
793							return {
794								label: probe.label,
795								selector: probe.selector,
796								width: Math.round(box.width),
797								height: Math.round(box.height),
798								properties: Object.fromEntries(
799									probe.properties.map((property) => [
800										property,
801										resolved.getPropertyValue(property),
802									]),
803								),
804							};
805						}),
806					probes.map((probe) => ({
807						label: probe.label,
808						selector: probe.selector,
809						properties: [...probe.properties],
810					})),
811				);
812			},
813			groupedText: async (probe) => {
814				if (livePages.size !== 1)
815					throw new Error('Witness grouped-text measurement requires exactly one live page');
816				const [page] = livePages;
817				if (page === undefined)
818					throw new Error('Witness grouped-text measurement requires exactly one live page');
819				return await page.evaluate(
820					(requested: {
821						group: string;
822						name: string;
823						nameAttribute: string | null;
824						item: string;
825					}) => {
826						/**
827						 * What the element renders to a reader. For a form control that
828						 * is its current value rather than its markup text: a text box
829						 * the application has written into shows the value, and its
830						 * `textContent` is whatever the template shipped.
831						 */
832						const rendered = (element: Element): string => {
833							if (
834								element instanceof HTMLInputElement ||
835								element instanceof HTMLTextAreaElement ||
836								element instanceof HTMLSelectElement
837							)
838								return element.value.trim();
839							return (element.textContent ?? '').trim();
840						};
841						const groups = [...document.querySelectorAll(requested.group)];
842						if (groups.length === 0)
843							throw new Error(`grouped-text probe matched no group: ${requested.group}`);
844						return groups.map((group) => {
845							const named = group.querySelector(requested.name);
846							if (named === null)
847								throw new Error(
848									`grouped-text probe matched no name element: ${requested.name}`,
849								);
850							const name =
851								requested.nameAttribute === null
852									? rendered(named)
853									: (named.getAttribute(requested.nameAttribute) ?? '');
854							if (name.length === 0)
855								throw new Error(
856									`grouped-text probe read an empty group name: ${requested.name}`,
857								);
858							return {
859								name,
860								items: [...group.querySelectorAll(requested.item)].map(rendered),
861							};
862						});
863					},
864					{
865						group: probe.group,
866						name: probe.name,
867						nameAttribute: probe.nameAttribute ?? null,
868						item: probe.item,
869					},
870				);
871			},
872			browserStorageKeys: async () => {
873				if (livePages.size !== 1)
874					throw new Error('Witness browser-storage measurement requires exactly one live page');
875				const [page] = livePages;
876				if (page === undefined)
877					throw new Error('Witness browser-storage measurement requires exactly one live page');
878				return await page.evaluate(() => ({
879					localStorage: Object.keys(globalThis.localStorage).sort(),
880					sessionStorage: Object.keys(globalThis.sessionStorage).sort(),
881				}));
882			},
883			serviceWorkerObserverFinalization: () => {
884				const finalization = observer?.readback() ?? null;
885				if (finalization === null)
886					throw new Error('Witness service-worker observer finalization is unavailable');
887				return finalization;
888			},
889			serviceWorkerTelemetry: async (timeoutMs) => {
890				const boundedTimeout = boundedTelemetryTimeout(timeoutMs);
891				if (livePages.size !== 1)
892					throw new Error('Witness service-worker telemetry requires exactly one live page');
893				const [page] = livePages;
894				if (page === undefined)
895					throw new Error('Witness service-worker telemetry requires exactly one live page');
896				const telemetry = await page.evaluate(
897					async ({ timeout }) => {
898						const state = await Promise.race([
899							navigator.serviceWorker.ready.then(() => 'ready' as const),
900							new Promise<'timeout'>((resolve) => {
901								globalThis.setTimeout(() => resolve('timeout'), timeout);
902							}),
903						]);
904						const registrations = await navigator.serviceWorker.getRegistrations();
905						const registration = registrations[0] ?? null;
906						const cacheNames = (await caches.keys()).sort();
907						const cacheEntries = await Promise.all(
908							cacheNames.map(async (name) => {
909								const cache = await caches.open(name);
910								const paths = (await cache.keys()).map((request) => {
911									const url = new URL(request.url);
912									if (url.origin !== location.origin)
913										throw new Error(
914											'service-worker cache contains a cross-origin request',
915										);
916									return `${url.pathname}${url.search}`;
917								});
918								return { name, paths: paths.sort() };
919							}),
920						);
921						return {
922							state,
923							registration: {
924								scriptPath:
925									registration?.active === null || registration?.active === undefined
926										? null
927										: new URL(registration.active.scriptURL).pathname,
928								scope:
929									registration === null ? null : new URL(registration.scope).pathname,
930								installing: registration?.installing?.state ?? null,
931								waiting: registration?.waiting?.state ?? null,
932								active: registration?.active?.state ?? null,
933							},
934							controller: navigator.serviceWorker.controller?.state ?? null,
935							cacheNames,
936							cacheEntries,
937						};
938					},
939					{ timeout: boundedTimeout },
940				);
941				return {
942					...telemetry,
943					workerEvents: [...workerEvents].sort((left, right) =>
944						JSON.stringify(left).localeCompare(JSON.stringify(right)),
945					),
946				} as ServiceWorkerTelemetry;
947			},
948		};
949	}
