551	function record(value: unknown, label: string): Record<string, unknown> {
552		if (value === null || typeof value !== 'object' || Array.isArray(value))
553			throw new Error(`Witness real-app ${label} must be an object`);
554		return value as Record<string, unknown>;
555	}
556	
557	function sha256Digest(value: unknown): value is string {
558		return typeof value === 'string' && value.length === 64;
559	}
560	
561	function sortedUniqueStrings(values: unknown): values is string[] {
562		return (
563			Array.isArray(values) &&
564			values.every((value) => typeof value === 'string') &&
565			new Set(values).size === values.length &&
566			values.join('\n') === [...values].sort().join('\n')
567		);
568	}
569	
570	function validServiceWorkerTelemetry(value: unknown): value is WitnessServiceWorkerTelemetry {
571		const telemetry = value as WitnessServiceWorkerTelemetry;
572		return (
573			telemetry?.state === 'ready' &&
574			telemetry.registration?.scriptPath === '/sw.js' &&
575			telemetry.registration.scope === '/' &&
576			telemetry.registration.active === 'activated' &&
577			(telemetry.controller === 'activated' || telemetry.controller === null) &&
578			sortedUniqueStrings(telemetry.cacheNames) &&
579			telemetry.cacheNames.length === 1 &&
580			Array.isArray(telemetry.cacheEntries) &&
581			telemetry.cacheEntries.length === 1 &&
582			telemetry.cacheEntries[0]?.name === telemetry.cacheNames[0] &&
583			sortedUniqueStrings(telemetry.cacheEntries[0].paths) &&
584			telemetry.cacheEntries[0].paths.length > 0 &&
585			telemetry.cacheEntries[0].paths.every((path) => path.startsWith('/')) &&
586			Array.isArray(telemetry.workerEvents)
