596	export function parseWitnessRealAppReceipt(value: unknown): WitnessRealAppReceipt {
597		const receipt = record(value, 'receipt') as WitnessRealAppReceipt;
598		if (
599			receipt.schemaVersion !== WITNESS_REAL_APP_SCHEMA ||
600			receipt.result !== 'pass' ||
601			!Array.isArray(receipt.runs) ||
602			receipt.runs.length !== WITNESS_REAL_APP_RUNS ||
603			!Array.isArray(receipt.canonicalReceipts) ||
604			receipt.canonicalReceipts.length !== WITNESS_REAL_APP_NAMES.length
605		)
606			throw new Error('Witness real-app receipt cardinality differs');
607		const expected = new Set<string>();
608		for (const app of WITNESS_REAL_APP_NAMES)
609			for (const lane of ['baseline', 'migrated'])
610				for (const pass of [1, 2]) expected.add(`${app}:${lane}:${pass}`);
611		const gestures = new Set<WitnessGesture>();
612		const semanticPasses = new Map<string, string>();
613		for (const run of receipt.runs) {
614			const key = `${run.app}:${run.lane}:${run.pass}`;
615			const served = run.servedStatic;
616			const servedStaticDiffers =
617				served?.transport !== 'isolated-bounded-loopback-production-static' ||
618				served.documentFallback !== 'index-only' ||
619				served.missingAssets !== '404' ||
620				served.traversal !== 'rejected' ||
621				!Number.isInteger(served.inventory?.files) ||
622				served.inventory.files < 1 ||
623				!sha256Digest(served.inventory.beforeSha256) ||
624				served.inventory.beforeSha256 !== served.inventory.afterSha256 ||
625				served.application?.path !== 'index.html' ||
626				!sha256Digest(served.application.beforeSha256) ||
627				served.application.beforeSha256 !== served.application.afterSha256 ||
628				!Array.isArray(served.serviceWorkers) ||
629				served.serviceWorkers.some(
630					(serviceWorker) =>
631						serviceWorker.path !== 'sw.js' ||
632						!sha256Digest(serviceWorker.beforeSha256) ||
