			documentFallback: 'index-only',
			missingAssets: '404',
			traversal: 'rejected',
			inventory: { files: 524, beforeSha256: digestOf('inventory'), afterSha256: digestOf('inventory') },
			application: {
				path: 'index.html',
				beforeSha256: digestOf(`index-${lane}`),
				afterSha256: digestOf(`index-${lane}`),
			},
